import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';
import { RichText } from './RichText';

// Class names are generated by styled-components, so compare markup without them.
const render = (text: string) => renderToStaticMarkup(<RichText text={text} />).replace(/ class="[^"]*"/g, '');

describe('RichText', () => {
  it('keeps basic formatting', () => {
    expect(render('<p>A <i>bold</i> <b>claim</b>.<br/>Next</p><ul><li>one</li></ul>')).toBe(
      '<div><p>A <i>bold</i> <b>claim</b>.<br/>Next</p><ul><li>one</li></ul></div>',
    );
  });

  it('drops scripts, handlers, styles and unsafe links', () => {
    const html = render(
      '<div style="color:red" onclick="alert(1)">Hi<script>alert(2)</script><img src=x onerror="alert(3)">' +
        '<a href="javascript:alert(4)">bad</a> <a href="https://example.com" onmouseover="x()">good</a></div>' +
        '<style>body{display:none}</style><iframe src="https://evil.example"></iframe>',
    );
    expect(html).toBe(
      '<div><div>Hibad <a href="https://example.com/" target="_blank" rel="noopener noreferrer nofollow">good</a></div></div>',
    );
    expect(html).not.toMatch(/alert|onerror|onclick|style|iframe|javascript/);
  });

  it('unwraps unknown elements and decodes entities', () => {
    expect(render('<font face="x">Caf&eacute; &amp; <h2>Heading</h2></font>')).toBe(
      '<div>Café &amp; <h4>Heading</h4></div>',
    );
  });

  it('leaves plain text alone', () => {
    expect(render('Plain 3 < 4 text')).toBe('<p>Plain 3 &lt; 4 text</p>');
  });
});
